// Method: CodeEdit::add_code_completion_option
static JSValue js_CodeEdit_add_code_completion_option(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "CodeEdit.add_code_completion_option: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "CodeEdit.add_code_completion_option: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    // Check WRITE rate limit (PRD Section 6.4)
    ExecutionLimiter* limiter = qjs_ctx->get_execution_limiter();
    if (limiter && !limiter->check_api_rate_limit(ApiCategory::WRITE)) {
        return JS_ThrowInternalError(ctx, "CodeEdit.add_code_completion_option: write rate limit exceeded");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "CodeEdit.add_code_completion_option: invalid or freed object");
    }

    CodeEdit* typed_obj = Object::cast_to<CodeEdit>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "CodeEdit.add_code_completion_option: object is not a CodeEdit");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 4) {
        return JS_ThrowTypeError(ctx, "CodeEdit.add_code_completion_option: expected at least 3 arguments, got %d", argc - 1);
    }

    // Convert arguments
    int64_t tmp_type; JS_ToInt64(ctx, &tmp_type, argv[1]); CodeEdit::CodeCompletionKind arg_type = (CodeEdit::CodeCompletionKind)tmp_type;
    const char* cstr_display_text = JS_ToCString(ctx, argv[2]); String arg_display_text = cstr_display_text ? String::utf8(cstr_display_text) : ""; JS_FreeCString(ctx, cstr_display_text);
    const char* cstr_insert_text = JS_ToCString(ctx, argv[3]); String arg_insert_text = cstr_insert_text ? String::utf8(cstr_insert_text) : ""; JS_FreeCString(ctx, cstr_insert_text);
    // Optional argument: text_color (default: Color(1, 1, 1, 1))
    Color arg_text_color = Color(1, 1, 1, 1);
    if (argc > 4) {
        // Override default with provided value
        // Complex type - use full conversion
        double tmp_r_text_color, tmp_g_text_color, tmp_b_text_color, tmp_a_text_color = 1.0;
    JSValue jr_text_color = JS_GetPropertyStr(ctx, argv[4], "r");
    JSValue jg_text_color = JS_GetPropertyStr(ctx, argv[4], "g");
    JSValue jb_text_color = JS_GetPropertyStr(ctx, argv[4], "b");
    JSValue ja_text_color = JS_GetPropertyStr(ctx, argv[4], "a");
    JS_ToFloat64(ctx, &tmp_r_text_color, jr_text_color);
    JS_ToFloat64(ctx, &tmp_g_text_color, jg_text_color);
    JS_ToFloat64(ctx, &tmp_b_text_color, jb_text_color);
    if (!JS_IsUndefined(ja_text_color)) JS_ToFloat64(ctx, &tmp_a_text_color, ja_text_color);
    JS_FreeValue(ctx, jr_text_color);
    JS_FreeValue(ctx, jg_text_color);
    JS_FreeValue(ctx, jb_text_color);
    JS_FreeValue(ctx, ja_text_color);
    Color arg_text_color(tmp_r_text_color, tmp_g_text_color, tmp_b_text_color, tmp_a_text_color);
    }
    // Optional argument: icon (default: nullptr)
    Ref<Resource> arg_icon = nullptr;
    if (argc > 5) {
        // Override default with provided value
        // Complex type - use full conversion
        Ref<Resource> arg_icon;
    if (JS_IsNumber(argv[5])) {
        // Direct handle (unwrapped by JS proxy)
        int64_t h_icon; JS_ToInt64(ctx, &h_icon, argv[5]);
        Object* obj_icon = qjs_ctx->get_object_registry()->get_object(h_icon);
        arg_icon = Ref<Resource>(Object::cast_to<Resource>(obj_icon));
    } else {
        // Object with __handle property
        JSValue jh_icon = JS_GetPropertyStr(ctx, argv[5], "__handle");
        if (!JS_IsUndefined(jh_icon)) {
            int64_t h_icon; JS_ToInt64(ctx, &h_icon, jh_icon);
            Object* obj_icon = qjs_ctx->get_object_registry()->get_object(h_icon);
            arg_icon = Ref<Resource>(Object::cast_to<Resource>(obj_icon));
        }
        JS_FreeValue(ctx, jh_icon);
    }
    }
    // Optional argument: value (default: nullptr)
    Variant arg_value = nullptr;
    if (argc > 6) {
        // Override default with provided value
        // Complex type - use full conversion
        Variant arg_value = qjs_ctx->js_to_variant(argv[6]);
    }
    // Optional argument: location (default: 1024)
    int64_t arg_location = 1024;
    if (argc > 7) {
        // Override default with provided value
        JS_ToInt64(ctx, &arg_location, argv[7]);
    }

    typed_obj->add_code_completion_option(arg_type, arg_display_text, arg_insert_text, arg_text_color, arg_icon, arg_value, arg_location);
    return JS_UNDEFINED;
}

